    CONSTRAINT dispatch_dossiers_excerpt_len CHECK ((char_length(excerpt) <= 500)),
    CONSTRAINT dispatch_dossiers_full_content_len CHECK ((char_length(full_content) <= 25000)),
    CONSTRAINT dispatch_dossiers_title_len CHECK ((char_length(title) <= 200))
);


