    CONSTRAINT mod_actions_action_check CHECK ((action = ANY (ARRAY['dismiss'::text, 'delete_content'::text, 'warn'::text, 'mute_user'::text, 'suspend'::text, 'ban'::text, 'permanent_exile'::text]))),
    CONSTRAINT mod_actions_content_snapshot_len CHECK ((char_length((content_snapshot)::text) <= 30000)),
    CONSTRAINT mod_actions_reason_len CHECK ((char_length(reason) <= 2000))
);


--
-- Name: COLUMN mod_actions.content_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mod_actions.content_snapshot IS 'What was removed, captured before deletion. Without it an appeal has nothing to look at, because get_report_evidence resolves the row live and returns found:false once it is gone.';


--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    type text DEFAULT 'system'::text,
    from_username text,
    message text NOT NULL,
    is_read boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    related_lounge_id uuid,
    film_id integer,
    poster_path text,
    from_user_id uuid,
    title text,
    body text,
    metadata jsonb,
    group_key text,
    CONSTRAINT notifications_body_len CHECK ((char_length(body) <= 1000)),
    CONSTRAINT notifications_from_username_len CHECK ((char_length(from_username) <= 100)),
    CONSTRAINT notifications_group_key_len CHECK ((char_length(group_key) <= 200)),
    CONSTRAINT notifications_message_len CHECK ((char_length(message) <= 1000)),
    CONSTRAINT notifications_metadata_len CHECK ((char_length((metadata)::text) <= 8000)),
    CONSTRAINT notifications_poster_path_len CHECK ((char_length(poster_path) <= 2048)),
    CONSTRAINT notifications_title_len CHECK ((char_length(title) <= 200)),
    CONSTRAINT notifications_type_check CHECK ((type = ANY (ARRAY['follow'::text, 'endorse'::text, 'comment'::text, 'annotate'::text, 'retransmit'::text, 'system'::text, 'reaction'::text, 'follow_request'::text, 'follow_accept'::text, 'moderation'::text])))
);


--
-- Name: COLUMN notifications.group_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.group_key IS 'Stable grouping identity declared by the writing trigger, e.g. endorse:log:<uuid>. The client groups on this and never infers identity from the message text (#73).';


