--
-- Name: profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.profiles (
    id uuid NOT NULL,
    username text NOT NULL,
    role text DEFAULT 'cinephile'::text,
    avatar_url text,
    bio text,
    favorite_films jsonb DEFAULT '[]'::jsonb,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    taste_seeds jsonb DEFAULT '[]'::jsonb,
    updated_at timestamp with time zone DEFAULT now(),
    is_social_private boolean DEFAULT false,
    tier text,
    persona text,
    followers_count integer DEFAULT 0,
    following_count integer DEFAULT 0,
    total_logs integer DEFAULT 0,
    following text[] DEFAULT '{}'::text[],
    followers text[] DEFAULT '{}'::text[],
    preferences jsonb DEFAULT '{}'::jsonb,
    display_name text,
    social_visibility text DEFAULT 'public'::text,
    badges jsonb DEFAULT '[]'::jsonb,
    current_streak integer DEFAULT 0,
    longest_streak integer DEFAULT 0,
    last_log_date date,
    email text,
    is_banned boolean DEFAULT false,
    ban_reason text DEFAULT ''::text,
    social_links jsonb DEFAULT '{}'::jsonb,
    is_founding boolean DEFAULT false,
    suspended_until timestamp with time zone,
    suspension_reason text,
    warning_count integer DEFAULT 0 NOT NULL,
    banned_at timestamp with time zone,
    member_no integer DEFAULT nextval('public.member_no_seq'::regclass),
    public_prefs jsonb GENERATED ALWAYS AS (public.public_prefs(preferences)) STORED,
    entitlement_source text,
    CONSTRAINT check_username_not_empty CHECK (((username IS NOT NULL) AND (username <> ''::text))),
    CONSTRAINT profiles_avatar_url_len CHECK ((char_length(avatar_url) <= 2048)),
    CONSTRAINT profiles_badges_len CHECK ((char_length((badges)::text) <= 8000)),
    CONSTRAINT profiles_ban_reason_len CHECK ((char_length(ban_reason) <= 2000)),
    CONSTRAINT profiles_bio_len CHECK ((char_length(bio) <= 160)),
    CONSTRAINT profiles_display_name_len CHECK ((char_length(display_name) <= 50)),
    CONSTRAINT profiles_email_len CHECK ((char_length(email) <= 320)),
    CONSTRAINT profiles_entitlement_source_check CHECK (((entitlement_source IS NULL) OR (entitlement_source = ANY (ARRAY['revenuecat'::text, 'paytabs'::text, 'manual'::text])))),
    CONSTRAINT profiles_favorite_films_len CHECK ((char_length((favorite_films)::text) <= 8000)),
    CONSTRAINT profiles_followers_len CHECK (((COALESCE(array_length(followers, 1), 0) <= 5000) AND (char_length(array_to_string(followers, ','::text)) <= 500000))),
    CONSTRAINT profiles_following_len CHECK (((COALESCE(array_length(following, 1), 0) <= 5000) AND (char_length(array_to_string(following, ','::text)) <= 500000))),
    CONSTRAINT profiles_persona_len CHECK ((char_length(persona) <= 50)),
    CONSTRAINT profiles_preferences_len CHECK ((char_length((preferences)::text) <= 8000)),
    CONSTRAINT profiles_public_prefs_len CHECK ((char_length((public_prefs)::text) <= 8000)),
    CONSTRAINT profiles_role_check CHECK ((role = ANY (ARRAY['free'::text, 'cinephile'::text, 'archivist'::text, 'auteur'::text, 'projectionist'::text, 'admin'::text]))),
    CONSTRAINT profiles_social_links_len CHECK ((char_length((social_links)::text) <= 4000)),
    CONSTRAINT profiles_social_visibility_check CHECK ((social_visibility = ANY (ARRAY['public'::text, 'members'::text, 'private'::text]))),
    CONSTRAINT profiles_suspension_reason_len CHECK ((char_length(suspension_reason) <= 2000)),
    CONSTRAINT profiles_taste_seeds_len CHECK ((char_length((taste_seeds)::text) <= 8000)),
    CONSTRAINT profiles_tier_check CHECK (((tier IS NULL) OR (tier = ANY (ARRAY['free'::text, 'cinephile'::text, 'archivist'::text, 'auteur'::text, 'founding'::text])))),
    CONSTRAINT profiles_tier_len CHECK ((char_length(tier) <= 100)),
    CONSTRAINT profiles_username_len CHECK ((char_length(username) <= 100))
);


