--
-- Name: lounge_message_reactions Approved members can react; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Approved members can react" ON public.lounge_message_reactions FOR INSERT WITH CHECK (((auth.uid() = user_id) AND (EXISTS ( SELECT 1
   FROM public.lounge_members m
  WHERE ((m.lounge_id = lounge_message_reactions.lounge_id) AND (m.user_id = auth.uid()) AND (m.status = 'approved'::text))))));


--
-- Name: lounge_messages Approved members can send; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Approved members can send" ON public.lounge_messages FOR INSERT WITH CHECK (((auth.uid() = user_id) AND (EXISTS ( SELECT 1
   FROM public.lounge_members m
  WHERE ((m.lounge_id = lounge_messages.lounge_id) AND (m.user_id = auth.uid()) AND (m.status = 'approved'::text))))));


